-- Synthetic users/company/documents only. No HTTP, email delivery or real case writes.
begin;
set local statement_timeout='20s';
set local lock_timeout='2s';
create function pg_temp.ex_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'EXEC QA: %',label;end if;perform set_config('ks.exec.checks',(coalesce(nullif(current_setting('ks.exec.checks',true),''),'0')::integer+1)::text,true);end$$;
create function pg_temp.ex_reject(query text,code text default null) returns void language plpgsql as $$declare failed boolean:=false;got text;begin begin execute query;exception when others then failed:=true;get stacked diagnostics got=returned_sqlstate;end;perform pg_temp.ex_assert(failed and (code is null or got=code),'rejected request, expected '||coalesce(code,'error')||', received '||coalesce(got,'success'));end$$;
do $$declare c uuid:=gen_random_uuid();u uuid;sys uuid;k text;pid uuid:=gen_random_uuid();begin
 insert into public.sales_company_scopes(id,normalized_name,display_name) values(c,public.sales_normalize_company_name('EXEC QA '||c),'EXEC QA '||c);perform set_config('ks.exec.company',c::text,true);
 select id into sys from public.profiles where system_role='systemadmin' and approved and not coalesce(deactivated,false) limit 1;assert sys is not null;perform set_config('ks.exec.sys',sys::text,true);
 foreach k in array array['admin','worker','colleague','isolated','without'] loop
  u:=gen_random_uuid();perform set_config('ks.exec.'||k,u::text,true);
  insert into auth.users(id,aud,role,email,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) values(u,'authenticated','authenticated','exec-qa-'||u||'@example.invalid',now(),now(),'{}',jsonb_build_object('full_name','EXEC QA '||k));
  insert into public.profiles(id,email,company_name,approved,deactivated,role,company_role) values(u,'exec-qa-'||u||'@example.invalid','EXEC QA '||c,true,false,case when k='admin' then 'admin' else 'member' end,case when k='admin' then 'firmaadmin' else 'ansatt' end) on conflict(id) do update set company_name=excluded.company_name,approved=true,deactivated=false,role=excluded.role,company_role=excluded.company_role,system_role=null;
  insert into public.sales_company_memberships(company_id,user_id,is_primary,workspace_role) values(c,u,true,case when k='admin' then 'firmaadmin' else 'ansatt' end) on conflict(company_id,user_id) do update set workspace_role=excluded.workspace_role;
  insert into public.user_active_company_scope(user_id,company_id) values(u,c) on conflict(user_id) do update set company_id=excluded.company_id;
  if k not in('isolated','without') then insert into public.user_module_access(user_id,module_key) values(u,'projects') on conflict do nothing;end if;
 end loop;
 insert into public.projects(id,user_id,company_scope_id,title,data) values(pid,current_setting('ks.exec.worker')::uuid,c,'EXEC QA project','{"project":{"projectName":"EXEC QA","projectDeviations":[{"id":"keep","status":"Åpent"}]},"overtagelse":{"signKunde":"keep"},"checklist":{"keep":{"comment":"Keep"}}}');perform set_config('ks.exec.project',pid::text,true);perform set_config('ks.exec.project.data',(select data::text from public.projects where id=pid),true);
end$$;
set local role authenticated;
do $$declare c uuid:=current_setting('ks.exec.company')::uuid;a uuid:=current_setting('ks.exec.admin')::uuid;u uuid:=current_setting('ks.exec.worker')::uuid;col uuid:=current_setting('ks.exec.colleague')::uuid;sid uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();mid uuid:=gen_random_uuid();pid uuid:=gen_random_uuid();req uuid;point uuid:=gen_random_uuid();content jsonb;payload jsonb;r jsonb;detail jsonb;before_snapshot jsonb;template jsonb;version_id uuid;risk_content jsonb;risk_row jsonb;k text;statement_value text:='Jeg bekrefter at jeg har gjennomført og kontrollert dokumentasjonen sammen med de oppgitte deltakerne.';
begin
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.sys'),true);perform public.kshms_activate(c,true);
 perform set_config('request.jwt.claim.sub',a::text,true);foreach k in array array['worker','colleague','isolated'] loop perform public.kshms_command(c,'access',jsonb_build_object('user_id',current_setting('ks.exec.'||k)::uuid,'role','reader','enabled',true));end loop;
 content:=jsonb_build_object('title','EXEC QA vernerunde','workplace','Lager','planned_on','2026-10-08','responsible_id',u,'participants','Utfører og verneombud gjennomgikk området.','review','Tiltak følges opp.','basis','','reference','','routines','R-001 versjon 1','acceptance',jsonb_build_object('low_max',4,'medium_max',12,'description','','confirmed',false),'risks','[]'::jsonb,'points',jsonb_build_array(jsonb_build_object('id',point,'title','Kontroller ferdsel','guidance','Se etter hindringer.','image_required',true,'comment_required',true)),'answers','{}'::jsonb);
 payload:=jsonb_build_object('id',sid,'kind','round','revision',0,'project_id',null,'template_version_id',null,'content',content,'confirmed',false,'statement',null);req:=gen_random_uuid();
 r:=public.kshms_execution_command(c,'save',req,payload);perform pg_temp.ex_assert(r#>>'{record,status}'='draft','partial draft saves without answers');perform pg_temp.ex_assert((r#>>'{record,revision}')::integer=1,'initial revision');
 perform pg_temp.ex_assert(public.kshms_execution_command(c,'save',req,payload)=r,'same request replays exact receipt');
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,req,payload||jsonb_build_object('revision',1)),'40001');
 perform set_config('request.jwt.claim.sub',col::text,true);perform pg_temp.ex_assert(jsonb_array_length(public.kshms_execution_state(c,'round')->'records')=0,'unassigned colleague cannot list private draft');perform pg_temp.ex_reject(format('select public.kshms_execution_detail(%L,%L)',c,sid),'42501');
 perform set_config('request.jwt.claim.sub',u::text,true);perform pg_temp.ex_assert(public.kshms_execution_detail(c,sid)#>>'{record,content,title}'=content->>'title','assigned user reads draft');perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,req,payload),'40001');
 payload:=payload||jsonb_build_object('revision',1,'confirmed',true,'statement',statement_value);perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''complete'',%L,%L::jsonb)',c,gen_random_uuid(),payload));
 content:=content||jsonb_build_object('answers',jsonb_build_object(point::text,jsonb_build_object('status','deviation','comment','Utstyr sperrer rømningsvei.','responsible_id',col,'due_on','2026-10-12','photos',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'data','data:image/png;base64,aGVsbG8=')))));payload:=payload||jsonb_build_object('content',content);
 perform set_config('request.jwt.claim.sub',a::text,true);perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''complete'',%L,%L::jsonb)',c,gen_random_uuid(),payload),'42501');
 perform set_config('request.jwt.claim.sub',u::text,true);perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''complete'',%L,%L::jsonb)',c,gen_random_uuid(),payload||'{"confirmed":false}'::jsonb),'42501');
 req:=gen_random_uuid();r:=public.kshms_execution_command(c,'complete',req,payload);detail:=public.kshms_execution_detail(c,sid);before_snapshot:=detail->'record';perform set_config('ks.exec.complete',sid::text,true);
 perform pg_temp.ex_assert(detail#>>'{record,status}'='completed','round completed');perform pg_temp.ex_assert(detail#>>'{record,completed_by}'=u::text,'own completion identity');perform pg_temp.ex_assert(detail#>>'{record,statement}'=statement_value,'exact confirmation');perform pg_temp.ex_assert(jsonb_array_length(detail->'links')=1,'one source-linked deviation');perform pg_temp.ex_assert(detail#>>'{links,0,case,responsible_id}'=col::text,'deviation assigned to chosen user');perform pg_temp.ex_assert(detail#>>'{links,0,case,status}'='open','completion does not close deviation');
 perform pg_temp.ex_assert(public.kshms_execution_command(c,'complete',req,payload)=r,'lost response retries complete idempotently');perform pg_temp.ex_assert(jsonb_array_length(public.kshms_execution_detail(c,sid)->'links')=1,'retry creates no second case');perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),payload||'{"revision":2}'::jsonb),'42501');
 perform set_config('request.jwt.claim.sub',col::text,true);detail:=public.kshms_execution_detail(c,sid);perform pg_temp.ex_assert(jsonb_array_length(public.kshms_execution_state(c,'round','completed')->'records')=1,'completed standalone round appears in company history');
 perform public.kshms_deviation_command(c,'close',jsonb_build_object('id',detail#>>'{links,0,case,id}','revision',1,'cause','OK','improvement_action','OK','control_note','OK','controlled',true));detail:=public.kshms_execution_detail(c,sid);perform pg_temp.ex_assert(detail#>>'{links,0,case,status}'='closed','follow-up reflects actual own closure');perform pg_temp.ex_assert(detail->'record'=before_snapshot,'closure never rewrites completed round');
 perform set_config('request.jwt.claim.sub',a::text,true);
 template:=public.kshms_checklist_command(c,'publish',gen_random_uuid(),jsonb_build_object('id',mid,'revision',0,'content',jsonb_build_object('title','EXEC QA firmamal','trade','Rørlegger','instructions','Kontroll før innbygging.','points',content->'points')));version_id:=(template#>>'{version,id}')::uuid;
 perform set_config('request.jwt.claim.sub',u::text,true);payload:=jsonb_build_object('id',rid,'kind','round','revision',0,'template_version_id',version_id,'content',content);r:=public.kshms_execution_command(c,'save',gen_random_uuid(),payload);perform pg_temp.ex_assert(public.kshms_execution_detail(c,rid)#>>'{record,template_snapshot,number}'='1','fixed published edition captured');
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),jsonb_set(payload||'{"revision":1}'::jsonb,'{content,points,0,title}','"Forged definition"'::jsonb)));
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),payload||jsonb_build_object('id',gen_random_uuid(),'template_version_id',gen_random_uuid())),'42501');
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.kshms_checklist_command(c,'publish',gen_random_uuid(),jsonb_build_object('id',mid,'revision',template#>>'{template,revision}','content',jsonb_set(template#>'{template,draft}','{points,0,title}','"Nytt punkt i versjon 2"'::jsonb)));
 perform set_config('request.jwt.claim.sub',u::text,true);perform pg_temp.ex_assert(public.kshms_execution_detail(c,rid)#>>'{record,template_snapshot,content,points,0,title}'='Kontroller ferdsel','later template publication preserves imported definition');
 risk_row:=jsonb_build_object('id',gen_random_uuid(),'activity','Kapping','hazard','Støv','consequence','Lungeskade','existing_measures','Avskjermet område','planned_measures','Avsug og kontroll','owner_id',col,'due_on','2026-10-12','probability_before',4,'consequence_before',5,'probability_after',1,'consequence_after',3,'follow_up','Verneombudet kontrollerer avsuget.','effect_status','planned','verified_on','','decision','accepted','reason','Forventet virkning må kontrolleres.');
 risk_content:=content||jsonb_build_object('title','EXEC QA risiko','points','[]'::jsonb,'answers','{}'::jsonb,'risks',jsonb_build_array(risk_row),'basis','Vurderingen gjelder dagens jobb og personskade. Nivåer er forklart for gruppen.','acceptance',jsonb_build_object('low_max',4,'medium_max',12,'description','Tiltak skal kontrolleres. Høy risiko krever stans/videre tiltak.','confirmed',true));payload:=jsonb_build_object('id',pid,'kind','risk','revision',0,'content',risk_content,'confirmed',true,'statement',statement_value);
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''complete'',%L,%L::jsonb)',c,gen_random_uuid(),payload));
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),jsonb_set(payload,'{content,risks,0,probability_before}','6'::jsonb)));
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),jsonb_set(payload,'{content,acceptance,low_max}','15'::jsonb)));
 payload:=jsonb_set(payload,'{content,risks,0,decision}','"needs_action"'::jsonb);r:=public.kshms_execution_command(c,'complete',gen_random_uuid(),payload);detail:=public.kshms_execution_detail(c,pid);perform pg_temp.ex_assert(detail#>>'{record,status}'='completed','complete assessment with planned outstanding actions');perform pg_temp.ex_assert(detail#>>'{record,content,risks,0,effect_status}'='planned','forecast is not rewritten as verified');perform pg_temp.ex_assert(detail#>>'{record,content,risks,0,decision}'='needs_action','explicit further-action decision');perform pg_temp.ex_assert(detail#>>'{record,completed_by}'=u::text,'risk completed by responsible');
 risk_content:=jsonb_set(jsonb_set(risk_content,'{risks,0,effect_status}','"verified"'::jsonb),'{risks,0,verified_on}','"2026-10-08"'::jsonb);payload:=jsonb_build_object('id',gen_random_uuid(),'kind','risk','revision',0,'content',risk_content,'confirmed',true,'statement',statement_value);r:=public.kshms_execution_command(c,'complete',gen_random_uuid(),payload);perform pg_temp.ex_assert(public.kshms_execution_detail(c,(r#>>'{record,id}')::uuid)#>>'{record,content,risks,0,decision}'='accepted','controlled effect and low score support explicit acceptance');
 payload:=jsonb_set(jsonb_set(payload||jsonb_build_object('id',gen_random_uuid()),'{content,risks,0,probability_after}','5'::jsonb),'{content,risks,0,consequence_after}','5'::jsonb);perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''complete'',%L,%L::jsonb)',c,gen_random_uuid(),payload));
 payload:=jsonb_build_object('id',gen_random_uuid(),'kind','round','revision',0,'project_id',current_setting('ks.exec.project'),'content',content);r:=public.kshms_execution_command(c,'save',gen_random_uuid(),payload);perform set_config('ks.exec.linked',(r#>>'{record,id}'),true);perform pg_temp.ex_assert(public.kshms_execution_detail(c,(r#>>'{record,id}')::uuid)#>>'{record,project_id}'=current_setting('ks.exec.project'),'project bound by actual ID');
 perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),payload||'{"revision":0}'::jsonb),'40001');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.isolated'),true);perform pg_temp.ex_reject(format('select public.kshms_execution_detail(%L,%L)',c,current_setting('ks.exec.linked')),'42501');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.without'),true);perform pg_temp.ex_reject(format('select public.kshms_execution_state(%L,''round'')',c),'42501');
 perform set_config('request.jwt.claim.sub',u::text,true);perform pg_temp.ex_reject(format('select public.kshms_execution_detail(%L,%L)',gen_random_uuid(),sid),'42501');
 perform pg_temp.ex_reject('select * from public.kshms_executions','42501');perform pg_temp.ex_reject('select * from public.kshms_execution_commands','42501');perform pg_temp.ex_reject('select * from public.kshms_execution_deviations','42501');
end$$;
reset role;
do $$declare c uuid:=current_setting('ks.exec.company')::uuid;sid uuid:=current_setting('ks.exec.complete')::uuid;pid uuid:=current_setting('ks.exec.project')::uuid;begin
 perform pg_temp.ex_reject(format('update public.kshms_executions set content=''{}'' where id=%L',sid),'42501');perform pg_temp.ex_reject(format('delete from public.kshms_executions where id=%L',sid),'42501');
 perform pg_temp.ex_assert((select data::text=current_setting('ks.exec.project.data') from public.projects where id=pid),'project checklist, deviations, signature and portal JSON unchanged');
 perform pg_temp.ex_assert((select count(*) from public.kshms_execution_deviations l join public.kshms_executions e on e.id=l.execution_id where e.company_id=c)=1,'one deviation despite complete retry');perform pg_temp.ex_assert((select count(*) from public.kshms_notification_outbox where company_id=c and notification_kind='deviation')=1,'one deviation assignment notification despite completion retry');
 update public.projects set locked=true where id=pid;
end$$;
set local role authenticated;
do $$declare c uuid:=current_setting('ks.exec.company')::uuid;sid uuid:=current_setting('ks.exec.linked')::uuid;r jsonb;begin
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.worker'),true);r:=public.kshms_execution_detail(c,sid);perform pg_temp.ex_assert(r#>>'{record,status}'='draft','locked project still allows reading');perform pg_temp.ex_reject(format('select public.kshms_execution_command(%L,''save'',%L,%L::jsonb)',c,gen_random_uuid(),r->'record'||jsonb_build_object('confirmed',false)));
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.sys'),true);perform public.kshms_activate(c,false);perform set_config('request.jwt.claim.sub',current_setting('ks.exec.worker'),true);perform pg_temp.ex_reject(format('select public.kshms_execution_state(%L,''round'')',c),'42501');perform pg_temp.ex_reject(format('select public.kshms_execution_detail(%L,%L)',c,sid),'42501');
end$$;
set local role anon;
do $$begin perform pg_temp.ex_reject(format('select public.kshms_execution_state(%L,''round'')',current_setting('ks.exec.company')),'42501');end$$;
reset role;

do $$declare c uuid:=current_setting('ks.exec.company')::uuid;pid uuid:=current_setting('ks.exec.project')::uuid;rid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();other_pid uuid:=gen_random_uuid();foreign_c uuid:=gen_random_uuid();foreign_pid uuid:=gen_random_uuid();begin
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.sys'),true);perform public.kshms_activate(c,true);
 insert into public.kshms_executions select (jsonb_populate_record(null::public.kshms_executions,to_jsonb(e)||jsonb_build_object('id',sid,'project_id',pid))).* from public.kshms_executions e where id=current_setting('ks.exec.complete')::uuid;
 perform set_config('ks.report.round',sid::text,true);
 insert into public.kshms_executions select (jsonb_populate_record(null::public.kshms_executions,to_jsonb(e)||jsonb_build_object('id',rid,'project_id',pid))).* from public.kshms_executions e where company_id=c and kind='risk' and status='completed' limit 1;
 perform set_config('ks.report.risk',rid::text,true);
 insert into public.projects(id,user_id,company_scope_id,title,data) values(other_pid,current_setting('ks.exec.worker')::uuid,c,'Other report QA','{}');perform set_config('ks.report.other_project',other_pid::text,true);
 insert into public.kshms_executions select (jsonb_populate_record(null::public.kshms_executions,to_jsonb(e)||jsonb_build_object('id',gen_random_uuid(),'project_id',other_pid))).* from public.kshms_executions e where id=sid;
 insert into public.sales_company_scopes(id,normalized_name,display_name) values(foreign_c,'report-foreign-'||foreign_c,'Report foreign QA');
 insert into public.projects(id,user_id,company_scope_id,title,data) values(foreign_pid,current_setting('ks.exec.without')::uuid,foreign_c,'Foreign report QA','{}');perform set_config('ks.report.foreign_project',foreign_pid::text,true);
 perform set_config('ks.report.private',gen_random_uuid()::text,true);
 insert into public.kshms_executions select (jsonb_populate_record(null::public.kshms_executions,to_jsonb(e)||jsonb_build_object('id',current_setting('ks.report.private')::uuid,'created_by',current_setting('ks.exec.admin')::uuid,'responsible_id',current_setting('ks.exec.admin')::uuid))).* from public.kshms_executions e where id=current_setting('ks.exec.linked')::uuid;
 perform set_config('ks.report.rows',(select md5(jsonb_agg(to_jsonb(e) order by id)::text) from public.kshms_executions e where company_id=c),true);
end$$;
set local role authenticated;
do $$declare c uuid:=current_setting('ks.exec.company')::uuid;pid uuid:=current_setting('ks.exec.project')::uuid;sid uuid:=current_setting('ks.report.round')::uuid;rid uuid:=current_setting('ks.report.risk')::uuid;draft uuid:=current_setting('ks.exec.linked')::uuid;r jsonb;begin
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.worker'),true);
 r:=public.kshms_project_execution_report(c,pid);perform pg_temp.ex_assert(jsonb_array_length(r#>'{choices,rounds}')=2,'completed and own draft rounds listed');perform pg_temp.ex_assert(jsonb_array_length(r#>'{choices,risks}')=1,'project risk listed');
 perform pg_temp.ex_assert(not (r#>'{choices,rounds,0}'?'content'),'choices never contain photos/content');
 r:=public.kshms_project_execution_report(c,pid,array[sid,draft],array[rid]);perform pg_temp.ex_assert(r#>>'{rounds,0,id}'=sid::text and r#>>'{rounds,1,id}'=draft::text,'requested order');perform pg_temp.ex_assert(r#>>'{rounds,0,status}'='completed','locked project completed export');perform pg_temp.ex_assert(r#>>'{rounds,1,status}'='draft','draft export explicit');perform pg_temp.ex_assert(r#>>'{rounds,0,content,answers}' is not null,'saved answers/photos returned');perform pg_temp.ex_assert(r#>>'{rounds,0,statement}' is not null,'saved completion statement');perform pg_temp.ex_assert(r#>>'{risks,0,content,risks,0,owner_identity}' is not null,'saved risk owner identity');perform pg_temp.ex_assert(r#>>'{context,project_id}'=pid::text,'project scope returned');
 perform pg_temp.ex_assert(public.kshms_project_execution_report(c,pid,'{}','{}')->'rounds'='[]'::jsonb,'empty selection safe');
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[%L]::uuid[],null)',c,pid,sid));
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[%L,%L]::uuid[],array[]::uuid[])',c,pid,sid,sid));
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[null]::uuid[],array[]::uuid[])',c,pid));
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[%L]::uuid[],array[]::uuid[])',c,pid,rid),'42501');
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[%L]::uuid[],array[]::uuid[])',c,current_setting('ks.report.other_project'),sid),'42501');
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',c,current_setting('ks.report.foreign_project')),'42501');
 perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L,array[%L]::uuid[],array[]::uuid[])',c,pid,current_setting('ks.report.private')),'42501');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.colleague'),true);perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',c,pid),'42501');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.isolated'),true);perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',c,pid),'42501');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.without'),true);perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',c,pid),'42501');
 perform set_config('request.jwt.claim.sub',current_setting('ks.exec.sys'),true);perform public.kshms_activate(c,false);perform set_config('request.jwt.claim.sub',current_setting('ks.exec.worker'),true);perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',c,pid),'42501');
end$$;
set local role anon;
do $$begin perform pg_temp.ex_reject(format('select public.kshms_project_execution_report(%L,%L)',current_setting('ks.exec.company'),current_setting('ks.exec.project')),'42501');end$$;
reset role;
do $$begin perform pg_temp.ex_assert((select md5(jsonb_agg(to_jsonb(e) order by id)::text)=current_setting('ks.report.rows') from public.kshms_executions e where company_id=current_setting('ks.exec.company')::uuid),'export never mutates executions');perform pg_temp.ex_assert((select data::text=current_setting('ks.exec.project.data') from public.projects where id=current_setting('ks.exec.project')::uuid),'export leaves project/portal JSON unchanged');end$$;

select 'PASS – all synthetic rows rolled back' as result,current_setting('ks.exec.checks')::integer as assertions;
rollback;
